// Готовим одну строку лога — валидный JSON без переводов строк.
const value = Number((18 + Math.random() * 12).toFixed(1));

msg.filename = "/data/krupa-ii241-log.jsonl";
msg.payload = JSON.stringify({
    ts: new Date().toISOString(),
    student: "Крупа Ксения (ИИ-241)",
    lab: 2,
    sensor: "temperature",
    value: value,
    unit: "C"
});

return msg;

// Файл читается целиком как строка. Разбираем его как JSON Lines.
const text = String(msg.payload || "").trim();

if (text === "") {
    msg.payload = {
        student: "Крупа Ксения (ИИ-241)",
        file: msg.filename,
        message: "Файл пуст — сначала нажмите «inject: записать показание»"
    };
    return msg;
}

const lines = text.split(/\r?\n/).filter(function (l) { return l.trim() !== ""; });

const entries = [];
for (const line of lines) {
    try {
        entries.push(JSON.parse(line));
    } catch (e) {
        // повреждённую строку пропускаем, чтобы не ронять поток
    }
}

const values = entries
    .map(function (e) { return e.value; })
    .filter(function (v) { return typeof v === "number"; });

let sum = 0;
for (const v of values) {
    sum += v;
}

msg.topic = "lab2/krupa-ii241/files";
msg.payload = {
    student: "Крупа Ксения (ИИ-241)",
    lab: 2,
    file: msg.filename,
    linesTotal: lines.length,
    parsedOk: entries.length,
    firstEntry: entries.length ? entries[0] : null,
    lastEntry: entries.length ? entries[entries.length - 1] : null,
    minValue: values.length ? Math.min.apply(null, values) : null,
    maxValue: values.length ? Math.max.apply(null, values) : null,
    avgValue: values.length ? Number((sum / values.length).toFixed(2)) : null
};

return msg;
